{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack has too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    values = stack[-count:]
    del stack[-count:]
    return values


def _divide(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    return quotient if (a < 0) == (b < 0) else -quotient


def _binary(func):
    def op(stack):
        a, b = _pop(stack, 2)
        stack.append(func(a, b))
    return op


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend([a, a])


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend([b, a])


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend([a, b, a])


BUILTINS = {
    '+': _binary(lambda a, b: a + b),
    '-': _binary(lambda a, b: a - b),
    '*': _binary(lambda a, b: a * b),
    '/': _binary(_divide),
    'dup': _dup,
    'drop': _drop,
    'swap': _swap,
    'over': _over,
}


def evaluate(input_data):
    stack = []
    # User definitions map a word to a list of already-expanded tokens:
    # numbers (int) or built-in operation names (str).
    definitions = {}

    def expand(token):
        if _is_number(token):
            return [int(token)]
        if token in definitions:
            return list(definitions[token])
        if token in BUILTINS:
            return [token]
        raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.lower().split()
        index = 0
        while index < len(tokens):
            token = tokens[index]
            if token == ':':
                try:
                    end = tokens.index(';', index + 1)
                except ValueError:
                    raise ValueError("undefined operation") from None
                if end - index < 2:
                    raise ValueError("undefined operation")
                name = tokens[index + 1]
                if _is_number(name):
                    raise ValueError("illegal operation")
                body = []
                for item in tokens[index + 2:end]:
                    body.extend(expand(item))
                definitions[name] = body
                index = end + 1
                continue
            for item in expand(token):
                if isinstance(item, int):
                    stack.append(item)
                else:
                    BUILTINS[item](stack)
            index += 1
    return stack
